-- Remaining editorial and book tables. Additive, non-destructive.
CREATE TABLE IF NOT EXISTS translation_validation_resolutions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,article_id BIGINT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,locale VARCHAR(20) NOT NULL,issue_key CHAR(64) NOT NULL,reason VARCHAR(1000) NOT NULL,source_hash CHAR(64) NOT NULL,translation_hash CHAR(64) NOT NULL,resolved_by BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,resolved_at TIMESTAMPTZ DEFAULT now(),UNIQUE(article_id,locale,issue_key));
CREATE INDEX IF NOT EXISTS idx_translation_res_article ON translation_validation_resolutions(article_id,locale);
CREATE TABLE IF NOT EXISTS article_revisions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,article_id BIGINT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,locale VARCHAR(20) NOT NULL,title VARCHAR(255),excerpt TEXT,content TEXT,seo_title VARCHAR(255),seo_description VARCHAR(320),seo_keywords VARCHAR(500),hashtags VARCHAR(500),featured_image VARCHAR(500),category_id BIGINT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS about_page_versions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,page_id BIGINT NOT NULL REFERENCES pages(id) ON DELETE CASCADE,locale VARCHAR(20) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),content_json TEXT NOT NULL,seo_title VARCHAR(255),seo_description VARCHAR(320),image_path VARCHAR(500),image_alt VARCHAR(255),created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,published_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),published_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_about_page_locale_status ON about_page_versions(page_id,locale,status);
CREATE INDEX IF NOT EXISTS idx_about_page_published ON about_page_versions(published_at);
CREATE TABLE IF NOT EXISTS editorial_threads (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,writer_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,article_id BIGINT REFERENCES articles(id) ON DELETE SET NULL,subject VARCHAR(190) NOT NULL,created_by BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status VARCHAR(12) NOT NULL DEFAULT 'open' CHECK(status IN ('open','archived')),created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_editorial_thread_writer ON editorial_threads(writer_id,status,updated_at);
CREATE INDEX IF NOT EXISTS idx_editorial_thread_article ON editorial_threads(article_id);
CREATE TABLE IF NOT EXISTS editorial_messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,thread_id BIGINT NOT NULL REFERENCES editorial_threads(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,read_at TIMESTAMP,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_editorial_message_thread ON editorial_messages(thread_id,id);
CREATE INDEX IF NOT EXISTS idx_editorial_message_sender ON editorial_messages(sender_id);
CREATE INDEX IF NOT EXISTS idx_editorial_message_read ON editorial_messages(read_at);
CREATE TABLE IF NOT EXISTS editorial_message_attachments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,message_id BIGINT NOT NULL REFERENCES editorial_messages(id) ON DELETE CASCADE,path VARCHAR(500) NOT NULL,original_name VARCHAR(240) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes BIGINT NOT NULL DEFAULT 0 CHECK(size_bytes>=0),created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_editorial_attachment_message ON editorial_message_attachments(message_id);
CREATE TABLE IF NOT EXISTS book_service_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,writer_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status VARCHAR(30) NOT NULL DEFAULT 'pending',active_slot SMALLINT DEFAULT 1 CHECK(active_slot>=0),admin_note TEXT,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(writer_id,active_slot));
CREATE INDEX IF NOT EXISTS idx_book_request_status ON book_service_requests(status,created_at);
CREATE TABLE IF NOT EXISTS book_agreements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id BIGINT NOT NULL REFERENCES book_service_requests(id) ON DELETE CASCADE,writer_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,version INTEGER NOT NULL CHECK(version>=0),terms TEXT NOT NULL,fee NUMERIC(12,2) NOT NULL DEFAULT 0,currency VARCHAR(8) NOT NULL DEFAULT 'USD',payment_terms TEXT,promo_scope TEXT,rights_terms TEXT,cancellation_terms TEXT,service_start DATE,service_end DATE,listing_after_expiry BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(20) NOT NULL DEFAULT 'offered',payment_status VARCHAR(20) NOT NULL DEFAULT 'pending',accepted_snapshot TEXT,accepted_at TIMESTAMP,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(request_id,version));
CREATE INDEX IF NOT EXISTS idx_book_agreement_writer ON book_agreements(writer_id,status);
CREATE INDEX IF NOT EXISTS idx_book_agreement_expiry ON book_agreements(service_end);
CREATE TABLE IF NOT EXISTS books (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,writer_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,agreement_id BIGINT NOT NULL REFERENCES book_agreements(id) ON DELETE CASCADE,title VARCHAR(240) NOT NULL,slug VARCHAR(260) NOT NULL UNIQUE,subtitle VARCHAR(240),genre VARCHAR(120),publisher VARCHAR(160),publication_year SMALLINT CHECK(publication_year>=0),isbn VARCHAR(32),book_language VARCHAR(40),page_count INTEGER CHECK(page_count>=0),book_format VARCHAR(80),description TEXT,front_media_id BIGINT REFERENCES media(id) ON DELETE SET NULL,back_media_id BIGINT REFERENCES media(id) ON DELETE SET NULL,purchase_url VARCHAR(1000),purchase_label VARCHAR(120),status VARCHAR(20) NOT NULL DEFAULT 'draft',is_featured BOOLEAN NOT NULL DEFAULT FALSE,promo_directory BOOLEAN NOT NULL DEFAULT TRUE,promo_profile BOOLEAN NOT NULL DEFAULT TRUE,promo_home BOOLEAN NOT NULL DEFAULT FALSE,published_at TIMESTAMP,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_books_writer ON books(writer_id,status,published_at);
CREATE INDEX IF NOT EXISTS idx_books_featured ON books(status,is_featured);
CREATE TABLE IF NOT EXISTS card_templates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,type VARCHAR(64) NOT NULL,name VARCHAR(190) NOT NULL,version VARCHAR(60) NOT NULL,path VARCHAR(500) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT FALSE,uploaded_by BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(type,version));
CREATE INDEX IF NOT EXISTS idx_card_template_active ON card_templates(type,is_active);
CREATE INDEX IF NOT EXISTS idx_card_template_uploader ON card_templates(uploaded_by,created_at);
